"use strict";const e=require("../common/vendor.js"),t=e.defineStore("user",{state:()=>({token:e.index.getStorageSync("bee_token")||"",user:e.index.getStorageSync("bee_user")||null}),actions:{setAuth(t,n){this.token=t,this.user=n,e.index.setStorageSync("bee_token",t),e.index.setStorageSync("bee_user",n)},logout(){this.token="",this.user=null,e.index.removeStorageSync("bee_token"),e.index.removeStorageSync("bee_user")},isLoggedIn(){return!!this.token}}});exports.useUserStore=t;
